/* Fictional, single-browser hackathon demo. No real child or device data. */
(()=>{
'use strict';
const KEY='diabuddy-fictional-family-demo-v1',seed={families:[{id:'family-demo',familyCode:'MISO01',plan:'free',expiresAt:null}],users:[{id:'parent-demo',role:'parent',name:'Sam Example',email:'sam@example.test',familyId:'family-demo'},{id:'kid-demo',role:'kid',name:'Sunny',familyId:'family-demo'}],kidProfiles:[{userId:'kid-demo',ageRange:'8to12',usesPump:false,usesCGM:false,deviceBrand:'None'}],characters:[{kidId:'kid-demo',name:'Miso',creatureType:'bunny',favoriteColor:'mint',world:'forest',interests:[],coins:0,lastMood:null}]};
const clone=x=>JSON.parse(JSON.stringify(x)),esc=escapeHTML,health='This is for learning, not medical advice. Always follow your care team’s plan.';let store;try{store=JSON.parse(localStorage.getItem(KEY)||'null')||clone(seed)}catch{store=clone(seed)}
if(!Array.isArray(store.journals))store.journals=[];
let page='start',step=0,role='parent',familyId=null,kidId=null,scanStream=null,scanFrame=null;
let draft={parentName:'Sam Example',email:'sam@example.test',kidName:'Sunny',childCount:1,ageRanges:[null],ageRange:'8to12',usesPump:false,usesCGM:false,deviceBrand:'None',plan:'free',planChoice:'free',name:'Miso',creatureType:'bunny',favoriteColor:'mint',world:'forest',interests:[]};
const unlocks={art:{label:'Art outfit & candy studio',clothes:'pink',world:'candy'},sports:{label:'Sports outfit & forest cabin',clothes:'overalls',world:'cabin'},music:{label:'Headphones & cozy room',accessory:'headphones',world:'cozy'},gaming:{label:'Galaxy hoodie & neon loft',clothes:'galaxy',world:'cyber'}};
const colorOutfits={mint:'shirt',pink:'pink',purple:'dress',blue:'pajamas',yellow:'costume',brown:'jacket',teal:'overalls'};
const planNames={free:'Free · $0',plusMonthly:'Plus Monthly · $5.99/month',plusAnnual:'Plus Annual · $50/year',familyMonthly:'Family Monthly · $8.99/month'};
const choices={creatures:[['bunny','Bunny 🐰'],['cat','Cat 🐱'],['dragon','Dragon 🐉']],colors:[['mint','Mint 🌿'],['pink','Pink 🌸'],['purple','Purple 💜'],['blue','Blue 🩵'],['yellow','Yellow ☀️'],['brown','Brown 🧸'],['teal','Teal 🐬']],worlds:[['space','Space 🚀'],['ocean','Ocean 🌊'],['forest','Forest 🌳']],interests:[['art','Art 🎨'],['sports','Sports ⚽'],['music','Music 🎵'],['gaming','Gaming 🎮']]};
function save(){try{localStorage.setItem(KEY,JSON.stringify(store));return true}catch{error('Couldn’t save the demo on this browser. Check storage and try again.');return false}}
function stopScan(){if(scanFrame)cancelAnimationFrame(scanFrame);scanFrame=null;if(scanStream)scanStream.getTracks().forEach(t=>t.stop());scanStream=null}
const modal=document.createElement('dialog');modal.id='family-demo';modal.className='family-demo';modal.setAttribute('aria-labelledby','family-title');document.body.appendChild(modal);
function error(message){const el=modal.querySelector('#family-error');if(el)el.textContent=message}
function select(key,options,multiple=false){return `<div class="family-options" role="group" aria-label="${esc(key)}">${options.map(([value,label])=>`<button type="button" data-pick="${esc(key)}" data-value="${esc(value)}" aria-pressed="${multiple?draft[key].includes(value):String(draft[key])===value}" class="family-option ${(multiple?draft[key].includes(value):String(draft[key])===value)?'selected':''}">${esc(label)}</button>`).join('')}</div>`}
function family(){return store.families.find(f=>f.id===familyId)}
function newCode(){const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';for(let tries=0;tries<100;tries++){const bytes=crypto.getRandomValues(new Uint8Array(6)),code=Array.from(bytes,n=>alphabet[n%alphabet.length]).join('');if(!store.families.some(f=>f.familyCode===code))return code}throw Error('code_unavailable')}
function id(){return crypto.randomUUID()}
function open(){window.DiaUX?.prepareDialog(modal);page='start';step=0;stopScan();if(!modal.open)modal.showModal();render()}
function show(next){stopScan();page=next;render()}
function content(){let title='',body='',actions='',progress='';
 if(page==='start'){title='Meet your DiaBuddy family';body=`<p>Try a pretend family on this browser. Names and email are fictional examples; please don’t enter real personal or health information.</p><div class="family-options"><button data-action="parent-start">👋 Parent setup</button><button data-action="kid-start">🐾 Kid setup</button><button data-action="seed">✨ Open the sample family</button></div><p class="family-hint">Sample code: <strong>MISO01</strong>. Codes and QR links work only in this browser; separate devices don’t share this demo.</p>`;}
 if(page==='parent'){const ages=draft.ageRanges.map((value,index)=>{const selected=draft.ageRange;draft.ageRange=value||'';const item= [`How old is child ${index+1}?`,`<p>Choose a fictional age range for child ${index+1}.</p>${select('ageRange',[['under8','Under 8'],['8to12','8–12'],['13plus','13+']])}`];draft.ageRange=selected;return item});const blocks=[['Your name and email',`<p>For this demo we’ll use a pretend parent account.</p><div class="family-example"><strong>Sam Example</strong><br>sam@example.test</div>`],['How many children with type 1 diabetes are you setting up?',`<p>Choose how many fictional children to include in this demo.</p>${select('childCount',Array.from({length:10},(_,i)=>[String(i+1),String(i+1)]))}`],...ages,['Children’s names or nicknames',`<p>For privacy, this demo uses fictional names.</p><div class="family-example">${draft.ageRanges.map((_,i)=>draft.childCount===1?'Sunny':`Sunny ${i+1}`).join('<br>')}</div>`],['Devices',`<p>Fictional labels for this demo; nothing connects or syncs.</p><p>Uses a pump?</p>${select('usesPump',[['true','Yes'],['false','No']])}<p>Uses a CGM?</p>${select('usesCGM',[['true','Yes'],['false','No']])}<label for="family-brand">Device brand</label><select id="family-brand">${['None','Dexcom'].map(x=>`<option ${draft.deviceBrand===x?'selected':''}>${x}</option>`).join('')}</select><p class="family-hint">${health}</p>`],['Choose a plan',`<p>You can change this anytime in the parent portal. This is a mock selection; no payment is collected.</p><div class="family-plan-options">${select('planChoice',[['free','Free · $0 · Basic features for all children'],['plusMonthly','Plus Monthly · $5.99/month · Premium features for 1 child'],['plusAnnual','Plus Annual · $50/year · Premium features for 1 child'],['familyMonthly','Family Monthly · $8.99/month · Premium features for up to 5 children']])}</div><p class="family-hint">Free includes games, learning, and a journal. Paid features are still being defined; insights are a fictional preview. Payment coming soon.</p>`]];progress=`PARENT SETUP · ${step+1} / ${blocks.length}`;[title,body]=blocks[step];actions=`<button class="secondary" data-action="back">← Back</button><button class="primary" data-action="parent-next">${step===blocks.length-1?'Create demo family':'Continue →'}</button>`}
 if(page==='link'){const f=family();title='Link your child';body=`<p>Your fictional family code is:</p><div class="family-code">${esc(f.familyCode)}</div><div id="family-qr" aria-label="QR code for demo family code"></div><p class="family-hint">${f.expiresAt?'Valid for 24 hours':'Sample code has no expiry'} in this browser only. No child information is included in the QR code. Account linking and guardian consent are not verified.</p><div class="family-options"><button data-action="kid-for-family">Continue to kid setup →</button></div>`;actions='<button class="secondary" data-action="start">← Back</button>'}
 if(page==='choose-child'){title='Who is setting up their buddy?';const kids=store.users.filter(u=>u.familyId===familyId&&u.role==='kid');body=`<p>Choose a fictional child from this demo family.</p><div class="family-options">${kids.map(u=>`<button type="button" data-child="${esc(u.id)}">${esc(u.name)}</button>`).join('')}</div>`;actions='<button class="secondary" data-action="kid-code-back">← Back</button>'}
 if(page==='kid'){progress=`KID SETUP · ${step+1} / 6`;const blocks=[['Enter your family code',`<p>Ask your grown-up for the six-letter demo code. Try <strong>MISO01</strong>.</p><label for="family-code-input">Family code</label><input id="family-code-input" maxlength="6" autocomplete="off" autocapitalize="characters" placeholder="MISO01" value="${esc(draft.code||'')}"><div class="family-scan"><button type="button" data-action="scan" ${(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia)?'disabled':''}>Scan QR code</button><video id="family-scan-video" playsinline muted hidden></video></div><p class="family-hint">Codes work in the same browser only.</p>`],['Name your character',`<p>Pick a pretend name for your buddy.</p>${select('name',[['Miso','Miso'],['Pip','Pip'],['Mochi','Mochi']])}`],['Pick a creature',`${select('creatureType',choices.creatures)}<canvas id="family-pet" width="160" height="140" aria-label="Your buddy preview"></canvas>`],['Pick a favorite color',select('favoriteColor',choices.colors)],['Pick a world',select('world',choices.worlds)],['What do you like?',`<p>Pick as many fictional interests as you like.</p>${select('interests',choices.interests,true)}<p class="family-hint">Each interest unlocks a matching demo outfit and world.</p>`]];[title,body]=blocks[step];actions=`<button class="secondary" data-action="back">← Back</button><button class="primary" data-action="kid-next">${step===5?'Meet my buddy':'Continue →'}</button>`}
 if(page==='parent-view'){const f=family(),children=store.users.filter(u=>u.familyId===f.id&&u.role==='kid');title='Your DiaBuddy family';body=`<div class="family-tabs"><button data-action="parent-view" aria-pressed="true">Parent view</button><button data-action="kid-view">Kid view</button></div><section class="family-example"><strong>Family code: ${esc(f.familyCode)}</strong><p>${children.map(c=>esc(c.name)).join(', ')||'No kid has joined yet.'}</p></section><h2>Subscription</h2><p>Current plan: <strong>${esc(planNames[f.planChoice]||(f.plan==='plus'?planNames.familyMonthly:planNames.free))}</strong></p><div class="family-options"><button data-plan="free" aria-pressed="${f.plan==='free'}">Free · $0</button><button data-plan="plus" aria-pressed="${f.plan==='plus'}">Family · $8.99/month</button></div><p class="family-hint">Payment coming soon. Plan changes are mock only.</p><h2>Parent insights</h2>${f.plan==='plus'?'<p>✨ Sample insight: Your buddy explored two games this week. This is fictional demo data.</p>':'<p>Unlock a fictional insights preview with Family Plus.</p><button data-plan="plus">Try Family Plus</button>'}<p class="family-hint">${health}</p>`;actions='<button class="secondary" data-action="start">← Demo menu</button><button class="primary" data-action="show-link">Show family code</button>'}
 if(page==='kid-view'){const f=family(),u=store.users.find(x=>x.id===kidId&&x.familyId===f.id)||store.users.find(x=>x.familyId===f.id&&x.role==='kid'),c=u&&store.characters.find(x=>x.kidId===u.id),profile=u&&store.kidProfiles.find(x=>x.userId===u.id),reading=({under8:'Pick a game and have fun with your buddy!', '8to12':'Explore a game or learn something new together.', '13plus':'Choose an activity to explore at your own pace.'})[profile?.ageRange]||'Explore at your own pace.';title=c?`Hi, ${esc(c.name)}!`:'Let’s meet your buddy!';body=`<div class="family-tabs"><button data-action="parent-view">Parent view</button><button data-action="kid-view" aria-pressed="true">Kid view</button></div>${c?`<canvas id="family-pet" width="200" height="180" aria-label="Your fictional buddy"></canvas><p>${esc(reading)}</p><p>${esc(c.creatureType)} · ${esc(c.favoriteColor)} · ${esc(c.world)} · ${c.coins} coins</p><p>Interests: ${c.interests.map(esc).join(', ')||'None yet'}</p>${store.journals.some(j=>j.kidId===u.id)?`<p>First demo journal mood: ${esc(store.journals.find(j=>j.kidId===u.id).mood)}</p>`:''}${c.interests.length?`<h2>Your unlocked looks</h2><div class="family-options">${c.interests.map(i=>`<button data-unlock="${esc(i)}" aria-pressed="${c.activeUnlock===i}">${esc(unlocks[i].label)}</button>`).join('')}</div>`:''}`:'<p>Choose a buddy to join this pretend family.</p>'}<p class="family-hint">${health}</p>`;actions=`<button class="secondary" data-action="start">← Demo menu</button><button class="primary" data-action="${c?'visit-world':'kid-for-family'}">${c?'Explore my little world':'Create a buddy →'}</button>`}
 return {title,body,actions,progress};}
function render(){const {title,body,actions,progress}=content();modal.innerHTML=`<div class="family-shell"><div class="family-top"><span>✿ &nbsp; DiaBuddy · FICTIONAL DEMO</span><button class="secondary" data-action="close" aria-label="Close family demo">×</button></div>${progress?`<div class="family-progress">${progress}</div>`:''}<h1 id="family-title" tabindex="-1">${title}</h1>${body}<p id="family-error" role="alert"></p><div class="family-actions">${actions}</div></div>`;modal.querySelector('#family-title').focus();const pet=modal.querySelector('#family-pet');if(pet){let species=draft.creatureType;if(page==='kid-view'){const k=store.users.find(u=>u.id===kidId)||store.users.find(u=>u.familyId===familyId&&u.role==='kid');species=store.characters.find(c=>c.kidId===k?.id)?.creatureType||'bunny'}const profile=page==='kid-view'?store.characters.find(c=>c.kidId===(store.users.find(u=>u.id===kidId)||store.users.find(u=>u.familyId===familyId&&u.role==='kid'))?.id):null;const look=profile?.activeUnlock?unlocks[profile.activeUnlock]:null;const room=look?.world||({space:'space',ocean:'beach',forest:'cabin'})[profile?.world]||'cozy';const clothes=look?.clothes||colorOutfits[profile?.favoriteColor]||'shirt';paintWorld(pet,room,{Characters:species,Clothes:clothes,Accessories:look?.accessory||null},'range','Idle',true,false)}const qr=modal.querySelector('#family-qr');if(qr){const q=qrcode(0,'M');q.addData(family().familyCode);q.make();qr.innerHTML=q.createImgTag(5,4);qr.querySelector('img').alt='QR code containing the six-character demo family code'} }
async function startScan(){if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia){error('QR scanning is not available here. Enter the code instead.');return}try{const detector=new BarcodeDetector({formats:['qr_code']});scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const video=modal.querySelector('#family-scan-video');video.hidden=false;video.srcObject=scanStream;await video.play();const loop=async()=>{try{const codes=await detector.detect(video);if(codes[0]?.rawValue){const code=codes[0].rawValue.trim().toUpperCase();if(/^[A-Z0-9]{6}$/.test(code)){draft.code=code;stopScan();render();return}}}catch{}if(scanStream)scanFrame=requestAnimationFrame(loop)};loop()}catch{stopScan();error('Camera unavailable. You can enter the code instead.')}}
function enterWorld(){const u=store.users.find(x=>x.id===kidId)||store.users.find(x=>x.familyId===familyId&&x.role==='kid'),buddy=u&&store.characters.find(x=>x.kidId===u.id);if(!buddy){step=0;show('kid');return}const outfit={Characters:buddy.creatureType,Clothes:colorOutfits[buddy.favoriteColor]||'shirt',Rooms:({forest:'cabin',ocean:'beach',space:'space'})[buddy.world]||'cozy'};window.DiaFamilyDemoActive=true;state={...state,characterName:buddy.name,equipped:{...state.equipped,...outfit},owned:[...new Set([...state.owned,...Object.values(outfit)])],coins:buddy.coins,entries:[],sharedMeal:null,timer:null,mealEvents:[],usedMealEvents:[]};stopScan();modal.close();const onboarding=document.querySelector('#onboarding');if(onboarding?.open)onboarding.close();go('home');window.DiaFamilyTour.start(buddy.name)}
function advanceKid(){if(step===0){const value=(modal.querySelector('#family-code-input').value||'').trim().toUpperCase();if(!/^[A-Z0-9]{6}$/.test(value)){error('Enter a six-character demo code.');return}const found=store.families.find(f=>f.familyCode===value);if(!found){error('That code doesn’t match. Try MISO01.');return}if(found.expiresAt&&Date.now()>=found.expiresAt){error('That code has expired. Ask for a new one.');return}familyId=found.id;draft.code=value;const kids=store.users.filter(x=>x.familyId===familyId&&x.role==='kid');if(kids.length>1){show('choose-child');return}kidId=kids[0]?.id||null}if(step<5){step++;render();return}const existing=store.users.find(x=>x.id===kidId&&x.familyId===familyId&&x.role==='kid')||store.users.find(x=>x.familyId===familyId&&x.role==='kid');if(existing){kidId=existing.id}else{kidId=id();store.users.push({id:kidId,role:'kid',name:draft.kidName,familyId});store.kidProfiles.push({userId:kidId,ageRange:draft.ageRange,usesPump:draft.usesPump,usesCGM:draft.usesCGM,deviceBrand:draft.deviceBrand})}const c={kidId,name:draft.name,creatureType:draft.creatureType,favoriteColor:draft.favoriteColor,world:draft.world,interests:[...draft.interests],coins:0};const old=store.characters.findIndex(x=>x.kidId===kidId);if(old>=0){c.coins=store.characters[old].coins;if('lastMood' in store.characters[old])c.lastMood=store.characters[old].lastMood;store.characters[old]=c}else store.characters.push(c);if(save())enterWorld()}
modal.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.child){const chosen=store.users.find(u=>u.id===b.dataset.child&&u.familyId===familyId&&u.role==='kid');if(chosen){kidId=chosen.id;step=1;show('kid')}return}if(b.dataset.pick){const k=b.dataset.pick,v=b.dataset.value;if(k==='interests')draft.interests=draft.interests.includes(v)?draft.interests.filter(i=>i!==v):[...draft.interests,v];else if(k==='childCount'){draft.childCount=Number(v);draft.ageRanges=Array.from({length:draft.childCount},(_,i)=>draft.ageRanges[i]||null)}else if(k==='ageRange'&&page==='parent'){draft.ageRanges[step-2]=v;draft.ageRange=v}else if(k==='usesPump'||k==='usesCGM')draft[k]=v==='true';else draft[k]=v;render();return}if(b.dataset.unlock){const u=store.users.find(x=>x.id===kidId)||store.users.find(x=>x.familyId===familyId&&x.role==='kid'),c=store.characters.find(x=>x.kidId===u?.id);if(c&&c.interests.includes(b.dataset.unlock)){c.activeUnlock=b.dataset.unlock;if(save())render()}return}if(b.dataset.plan){const f=family(),old=f.plan,oldChoice=f.planChoice;if(b.dataset.plan==='plus'&&store.users.filter(u=>u.familyId===f.id&&u.role==='kid').length>5){error('Family covers up to five children. Free remains available.');return}f.plan=b.dataset.plan;f.planChoice=f.plan==='free'?'free':'familyMonthly';if(save())render();else{f.plan=old;f.planChoice=oldChoice}return}switch(b.dataset.action){case'close':stopScan();modal.close();break;case'start':show('start');break;case'parent-start':draft={...draft,plan:'free',planChoice:'free'};step=0;show('parent');break;case'kid-start':draft.code='';kidId=null;step=0;show('kid');break;case'seed':familyId='family-demo';kidId='kid-demo';show('parent-view');break;case'parent-view':show('parent-view');break;case'kid-view':show('kid-view');break;case'show-link':show('link');break;case'kid-for-family':draft.code=family().familyCode;step=0;show('kid');break;case'kid-code-back':step=0;show('kid');break;case'back':if(step>0){step--;render()}else show('start');break;case'scan':startScan();break;case'visit-world':enterWorld();break;case'parent-next':if(step>=2&&step<2+draft.childCount&&!draft.ageRanges[step-2]){error('Please choose an age range to continue.');break}if(step===3+draft.childCount)draft.deviceBrand=modal.querySelector('#family-brand').value;if(step<4+draft.childCount){step++;render();break}if((draft.planChoice==='plusMonthly'||draft.planChoice==='plusAnnual')&&draft.childCount>1){error('Plus covers one child. Choose Free or Family for more children.');break}if(draft.planChoice==='familyMonthly'&&draft.childCount>5){error('Family covers up to five children. Choose Free for this demo family.');break}try{const fid=id(),pid=id(),code=newCode();store.families.push({id:fid,familyCode:code,plan:draft.planChoice==='free'?'free':'plus',planChoice:draft.planChoice,expiresAt:Date.now()+86400000});store.users.push({id:pid,role:'parent',name:draft.parentName,email:draft.email,familyId:fid});for(let i=0;i<draft.childCount;i++){const kid=id();store.users.push({id:kid,role:'kid',name:draft.childCount===1?'Sunny':`Sunny ${i+1}`,familyId:fid});store.kidProfiles.push({userId:kid,ageRange:draft.ageRanges[i],usesPump:draft.usesPump,usesCGM:draft.usesCGM,deviceBrand:draft.deviceBrand});if(i===0)kidId=kid}familyId=fid;if(save())show('link')}catch{error('Couldn’t create a demo code. Please try again.')}break;case'kid-next':advanceKid();break}});
window.DiaFamilyDemo={stopForCare(){if(modal.open){stopScan();modal.close();}}};
modal.addEventListener('cancel',()=>stopScan());modal.addEventListener('close',()=>stopScan());document.addEventListener('click',event=>{if(event.target.closest('[data-family-demo]'))open()});
const banner=document.querySelector('.demo-privacy-banner');if(banner){const button=document.createElement('button');button.type='button';button.className='text-link';button.dataset.familyDemo='';button.textContent='Open family linking demo';banner.append(' ',button)}
})();
